#include <bits/stdc++.h>
#define rep(i,n) for (int i = 0; i < n; i++)
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> pi;
typedef pair<pi, pi> pp;
typedef pair<ll, ll> pl;
const double EPS = 1e-9;
const ll MOD = 1000000007;
const int inf = 1 << 30;
const ll linf = 1LL << 60;

struct edge{int to, cap, cost, rev; };

struct MinCostFlow {
    #define MAX_VERTICES 5010
    int V;
    vector<edge> G[MAX_VERTICES];
    int h[MAX_VERTICES];
    int dist[MAX_VERTICES];
    int prevv[MAX_VERTICES], preve[MAX_VERTICES];

    void initialize(int n) {
        V = n;
    }

    void addEdge(int from, int to, int cap, int cost){
        G[from].push_back((edge){to, cap, cost, (int)G[to].size()});
        G[to].push_back((edge){from, 0, -cost, (int)G[from].size()-1});
    }

    int computeMinCostFlow(int s, int t, int flow){
        int totalCost = 0;
        fill(h, h+V, 0);
        while(flow > 0){    
            priority_queue<pi, vector<pi>, greater<pi> > pq;
            fill(dist, dist+V, inf);
            dist[s] = 0;
            pq.push(pi(0,s));
            while(!pq.empty()){
                pi p = pq.top(); pq.pop();
                int v = p.second;
                if(dist[v] < p.first) continue;
                for(int i = 0; i < G[v].size(); i++){
                    edge &e = G[v][i];
                    if(e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]){
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push(pi(dist[e.to],e.to));
                    }
                }
            }
            if(dist[t] == inf){
                return -1;
            }
            for(int v = 0; v < V; v++) h[v] += dist[v];
            int d = flow;
            for(int v = t; v != s; v = prevv[v]){
                d = min(d, G[prevv[v]][preve[v]].cap);
            }
            flow -= d;
            totalCost += d * h[t];
            for(int v = t; v != s; v = prevv[v]){
                edge &e = G[prevv[v]][preve[v]];
                e.cap -= d;
                G[v][e.rev].cap += d;
            }
        }
        return totalCost;
    }
};

MinCostFlow minCostFlowSolver;

int n, m, k, c, d;
int a[50];
int countArr[50];
vector<int> adj[50];

const int T = 100;

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    rep(i,k) scanf("%d", a+i);
    rep(i,k) countArr[a[i]-1]++;
    rep(i,m) {
        int x, y; scanf("%d%d", &x, &y);
        x--; y--;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    minCostFlowSolver.initialize(n*T+2);
    rep(i,n) minCostFlowSolver.addEdge(n*T, i, countArr[i], 0);
    rep(i,T) minCostFlowSolver.addEdge(i*n, n*T+1, k, c*i);
    rep(i,n) {
        rep(j,T-1) minCostFlowSolver.addEdge(j*n+i, (j+1)*n+i, k, 0);
        for (int to: adj[i]) {
            rep(j,T-1) {
                rep(u,k) {
                    int cost = (u+1)*(u+1)*d - u*u*d;
                    minCostFlowSolver.addEdge(j*n+i, (j+1)*n+to, 1, cost);
                }
            }
        }
    }
    printf("%d\n", minCostFlowSolver.computeMinCostFlow(n*T, n*T+1, k));
}
